// מדמה שליפת סטטוס הזמנה ממסד הנתונים של החברה
const orderId = $('Webhook').first().json.body.order_id;

const mockOrderDatabase = {
  '12345': { status: 'בדרך אליך', carrier: 'שליחים אקספרס', tracking: 'IL998877', estimated_delivery: '2026-09-18', order_total_ils: 278, items: 'בקבוק תרמי GreenFlask, תיק גב EcoPack', final_sale: false },
  '67890': { status: 'נמסר', carrier: 'דואר ישראל', tracking: 'IL112233', delivered_at: '2026-09-10', order_total_ils: 89, items: 'בקבוק תרמי GreenFlask 500 מל', final_sale: false },
  '55555': { status: 'מתעכב במחסן', carrier: 'שליחים אקספרס', tracking: 'IL445566', estimated_delivery: '2026-09-22', order_total_ils: 129, items: 'ערכת כלי מטבח במבוק BambooChef', final_sale: false },
  '77777': { status: 'נמסר', carrier: 'דואר ישראל', tracking: 'IL778899', delivered_at: '2026-09-05', order_total_ils: 149, items: 'מנורת שולחן סולארית SunDesk (מבצע סוף עונה)', final_sale: true }
};

const order = mockOrderDatabase[orderId];

return [{
  json: order
    ? { success: true, order_id: orderId, ...order }
    : { success: false, order_id: orderId, error: 'מספר הזמנה לא נמצא במערכת' }
}];

// מדמה יצירת קופון פיצוי ורישום בקשת החזר במערכת
const body = $('Webhook').first().json.body;
const orderId = body.order_id;
const details = body.details || '';

// אותו מסד נתונים כמו בצומת סטטוס ההזמנה - הפיצוי נגזר משווי ההזמנה בפועל
const mockOrderDatabase = {
  '12345': { order_total_ils: 278, final_sale: false },
  '67890': { order_total_ils: 89, final_sale: false },
  '55555': { order_total_ils: 129, final_sale: false },
  '77777': { order_total_ils: 149, final_sale: true }
};

const order = mockOrderDatabase[orderId];

if (!order) {
  return [{ json: { success: false, order_id: orderId, error: 'מספר הזמנה לא נמצא במערכת' } }];
}

// מוצר במבצע "כל המכירות סופיות" אינו ניתן להחזרה, אלא אם הגיע פגום
if (order.final_sale) {
  return [{
    json: {
      success: false,
      order_id: orderId,
      error: 'ההזמנה כוללת מוצר במבצע "כל המכירות סופיות" ואינה ניתנת להחזרה',
      policy_note: 'ניתן להחזיר רק אם המוצר הגיע פגום - נדרש בירור מול נציג אנושי',
      reason: details
    }
  }];
}

// מדיניות החברה: הפיצוי לא יעלה על שווי ההזמנה, ולא על תקרת הפקיד
const MAX_COMPENSATION_ILS = 200;
const compensation = Math.min(order.order_total_ils, MAX_COMPENSATION_ILS);
const couponCode = 'GS-' + Math.random().toString(36).substring(2, 8).toUpperCase();

return [{
  json: {
    success: true,
    order_id: orderId,
    refund_request_id: 'REF-' + orderId,
    status: 'הבקשה נרשמה וממתינה לאישור',
    order_total_ils: order.order_total_ils,
    compensation_coupon: couponCode,
    compensation_value_ils: compensation,
    note: 'הזיכוי יתבצע תוך 5-7 ימי עסקים ממועד קבלת המוצר במחסן',
    reason: details
  }
}];
